#!/usr/bin/env python3
"""make_native.py -- JUNO-60.exe as ONE self-contained Windows program: the C99
port (the same sources as libjuno.so, compiled natively) under the plugin's own
panel (gui/win/juno60_win.c), with Script.xml, the sprite sheets and the banks
EMBEDDED as resources. For the USER'S OWN machine: it holds Roland's artwork and
the user's banks, so it is written to scratchpad/ (gitignored) -- never publish
it, never commit it.

  scratchpad/dist/native/assets.h   the resource ids (generated)
  scratchpad/dist/native/assets.rc  Script.xml, the 31 sheets, the bank blob
  scratchpad/dist/native/banks.rle  Factory + scratchpad/userbanks/*.bin, zero-run
                                    coded: u32 count; per bank u16 name length,
                                    name, u32 size, u32 coded size, code (byte
                                    b != 0: itself; 0, lo, hi: that many zeros)
  scratchpad/dist/JUNO-60.exe       the program

USAGE  python3 tools/dist/make_native.py [--no-userbanks]
"""
import os
import shutil
import struct
import subprocess
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.dirname(os.path.dirname(HERE))
sys.path.insert(0, os.path.join(REPO, 'tools', 'verify'))
import truth  # noqa: E402

OUT = os.path.join(REPO, 'scratchpad', 'dist')
BUILD = os.path.join(OUT, 'native')
EXE = os.path.join(OUT, 'JUNO-60.exe')

ID_XML, ID_BANKS, ID_PNG0 = 100, 101, 200
# the port's own build flags (Makefile): -ffp-contract=off is load-bearing
CFLAGS = ['-std=c99', '-O2', '-ffp-contract=off', '-fno-strict-aliasing', '-Wall', '-Wno-unused-function']
LIBS = ['-lgdiplus', '-lshlwapi', '-lwinmm', '-lcomdlg32', '-lgdi32', '-lole32', '-lshell32', '-lm']


def rle0(data):
    """zero runs -> 0, lo, hi (runs up to 65535); every other byte as itself"""
    out = bytearray()
    i, n = 0, len(data)
    while i < n:
        if data[i]:
            out.append(data[i])
            i += 1
            continue
        j = i
        while j < n and not data[j] and j - i < 65535:
            j += 1
        out += bytes((0, (j - i) & 0xff, (j - i) >> 8))
        i = j
    return bytes(out)


def unrle0(code, size):
    out = bytearray(size)
    o = k = 0
    while k < len(code):
        if code[k]:
            out[o] = code[k]
            o += 1
            k += 1
        else:
            o += code[k + 1] | (code[k + 2] << 8)
            k += 3
    assert o == size
    return bytes(out)


def bank_list(with_user):
    banks = [('Factory', truth.BANK)]
    udir = os.path.join(REPO, 'scratchpad', 'userbanks')
    if with_user and os.path.isdir(udir):
        for f in sorted(os.listdir(udir)):
            if f.lower().endswith('.bin'):
                banks.append((os.path.splitext(f)[0].lstrip('~').strip(), os.path.join(udir, f)))
    return banks


def banks_blob(banks):
    blob = bytearray(struct.pack('<I', len(banks)))
    for name, path in banks:
        raw = open(path, 'rb').read()
        if raw[:16] != b'KoaBankFile00003':
            raise SystemExit('%s: not a JUNO-60 bank file' % path)
        code = rle0(raw)
        assert unrle0(code, len(raw)) == raw            # the code round-trips
        nm = name.encode('ascii', 'replace')[:60]
        blob += struct.pack('<H', len(nm)) + nm + struct.pack('<II', len(raw), len(code)) + code
    return bytes(blob)


def rc_path(p):
    return p.replace('\\', '/').replace('"', '')


def main():
    with_user = '--no-userbanks' not in sys.argv
    truth.verify()                                       # the pinned bytes, artwork included
    cc = shutil.which('x86_64-w64-mingw32-gcc')
    rc = shutil.which('x86_64-w64-mingw32-windres')
    if not cc or not rc:
        raise SystemExit('mingw-w64 not found (apt-get install mingw-w64)')
    if os.path.exists(BUILD):
        shutil.rmtree(BUILD)
    os.makedirs(BUILD)
    sdir = os.path.join(truth.TRUTH_DIR, 'Script')
    pngs = sorted(f for f in os.listdir(sdir) if f.endswith('.png'))
    banks = bank_list(with_user)
    with open(os.path.join(BUILD, 'banks.rle'), 'wb') as f:
        f.write(banks_blob(banks))
    with open(os.path.join(BUILD, 'assets.h'), 'w') as f:
        f.write('/* generated by tools/dist/make_native.py -- do not edit */\n')
        f.write('#define ASSET_SCRIPT_XML %d\n#define ASSET_BANKS %d\n' % (ID_XML, ID_BANKS))
        f.write('static const struct { const char *name; int id; } ASSET_PNG[] = {\n')
        for i, p in enumerate(pngs):
            f.write('    {"%s", %d},\n' % (p, ID_PNG0 + i))
        f.write('};\n#define ASSET_PNG_N %d\n' % len(pngs))
    with open(os.path.join(BUILD, 'assets.rc'), 'w') as f:
        f.write('%d RCDATA "%s"\n' % (ID_XML, rc_path(truth.SCRIPT_XML)))
        f.write('%d RCDATA "%s"\n' % (ID_BANKS, rc_path(os.path.join(BUILD, 'banks.rle'))))
        for i, p in enumerate(pngs):
            f.write('%d RCDATA "%s"\n' % (ID_PNG0 + i, rc_path(os.path.join(sdir, p))))
    res = os.path.join(BUILD, 'assets.res.o')
    subprocess.check_call([rc, '-O', 'coff', '-o', res, os.path.join(BUILD, 'assets.rc')])
    srcs = [os.path.join(REPO, 'gui', 'win', 'juno60_win.c'), os.path.join(REPO, 'gui', 'juno_bridge.c')]
    srcs += sorted(os.path.join(REPO, 'src', f) for f in os.listdir(os.path.join(REPO, 'src')) if f.endswith('.c'))
    subprocess.check_call([cc] + CFLAGS + ['-mwindows', '-I', BUILD, '-I', os.path.join(REPO, 'src'),
                                           '-o', EXE] + srcs + [res] + LIBS + ['-s'])
    print('banks: %s' % ', '.join(n for n, _ in banks))
    print('wrote %s (%d bytes)' % (EXE, os.path.getsize(EXE)))
    return 0


if __name__ == '__main__':
    sys.exit(main())
